export interface CoinAnalysisResult {
  rarityScore: number;
  rarityLevel: string;
  reasoning: string;
  estimatedValue: string;
  narrationScript: string;
  coinName: string;
  year?: string;
  mintMark?: string;
}

export enum AnalysisStatus {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  GENERATING_AUDIO = 'GENERATING_AUDIO',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

export interface AudioState {
  isPlaying: boolean;
  blobUrl: string | null;
  isLoading: boolean;
}

// Helper to decode base64 string to Uint8Array
export const base64ToUint8Array = (base64: string): Uint8Array => {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

// Convert Raw PCM 16-bit LE to WAV Blob
export const pcmToWavBlob = (pcmData: Uint8Array, sampleRate: number = 24000, numChannels: number = 1): Blob => {
  const bytesPerSample = 2; // 16-bit
  const blockAlign = numChannels * bytesPerSample;
  const byteRate = sampleRate * blockAlign;
  const dataSize = pcmData.length;
  const buffer = new ArrayBuffer(44 + dataSize);
  const view = new DataView(buffer);

  // RIFF identifier
  writeString(view, 0, 'RIFF');
  // file length
  view.setUint32(4, 36 + dataSize, true);
  // RIFF type
  writeString(view, 8, 'WAVE');
  // format chunk identifier
  writeString(view, 12, 'fmt ');
  // format chunk length
  view.setUint32(16, 16, true);
  // sample format (raw)
  view.setUint16(20, 1, true);
  // channel count
  view.setUint16(22, numChannels, true);
  // sample rate
  view.setUint32(24, sampleRate, true);
  // byte rate (sample rate * block align)
  view.setUint32(28, byteRate, true);
  // block align (channel count * bytes per sample)
  view.setUint16(32, blockAlign, true);
  // bits per sample
  view.setUint16(34, 16, true);
  // data chunk identifier
  writeString(view, 36, 'data');
  // data chunk length
  view.setUint32(40, dataSize, true);

  // Write PCM data
  const pcmBytes = new Uint8Array(buffer, 44);
  pcmBytes.set(pcmData);

  return new Blob([buffer], { type: 'audio/wav' });
};

const writeString = (view: DataView, offset: number, string: string) => {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
};

import { GoogleGenAI, Type, Schema, Modality } from "@google/genai";
import { CoinAnalysisResult } from '../types';
import { base64ToUint8Array, pcmToWavBlob } from '../utils/audioUtils';

// Initialize the Gemini Client
// CRITICAL: The API key is injected via process.env.API_KEY
const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please ensure process.env.API_KEY is available.");
  }
  return new GoogleGenAI({ apiKey });
};

export const analyzeCoinImage = async (base64Image: string): Promise<CoinAnalysisResult> => {
  const ai = getAiClient();

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      coinName: { type: Type.STRING, description: "The name of the coin (e.g., Washington Quarter)." },
      year: { type: Type.STRING, description: "The year minted, if visible." },
      mintMark: { type: Type.STRING, description: "The mint mark, if visible." },
      rarityScore: { type: Type.NUMBER, description: "A score from 1 to 10 based on rarity and condition." },
      rarityLevel: { type: Type.STRING, description: "Common, Scarce, Rare, or Ultra-Rare." },
      reasoning: { type: Type.STRING, description: "Detailed reasoning for the score, mentioning errors or key features." },
      estimatedValue: { type: Type.STRING, description: "Estimated market value range (e.g., $10 - $50)." },
      narrationScript: { type: Type.STRING, description: "A conversational, enthusiastic script for a narrator to explain these findings to the user. Approx 50-80 words." }
    },
    required: ["coinName", "rarityScore", "rarityLevel", "reasoning", "estimatedValue", "narrationScript"]
  };

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image
          }
        },
        {
          text: `Analyze this coin image carefully. Identify if it is a specific error coin (like double die) or a standard issue. Provide a rarity assessment and value estimation. Write a narration script that sounds like a professional numismatist excitedly explaining the find to a collector.`
        }
      ]
    },
    config: {
      responseMimeType: 'application/json',
      responseSchema: schema,
      systemInstruction: "You are a world-class numismatist (coin expert). You are precise, knowledgeable, and enthusiastic about rare finds.",
      temperature: 0.4
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");

  return JSON.parse(text) as CoinAnalysisResult;
};

export const generateNarrationAudio = async (text: string): Promise<string> => {
  const ai = getAiClient();

  const response = await ai.models.generateContent({
    model: 'gemini-2.5-flash-preview-tts',
    contents: {
      parts: [{ text }]
    },
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          // 'Fenrir' is a deep, energetic voice suitable for an "expert" persona
          prebuiltVoiceConfig: { voiceName: 'Fenrir' }
        }
      }
    }
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;

  if (!base64Audio) {
    throw new Error("Failed to generate audio content");
  }

  // Decode and Convert to WAV Blob URL for playback
  const pcmData = base64ToUint8Array(base64Audio);
  const wavBlob = pcmToWavBlob(pcmData, 24000); // 24kHz is standard for this model
  return URL.createObjectURL(wavBlob);
};

import React, { useState, useRef, useEffect } from 'react';
import { AnalysisStatus, CoinAnalysisResult } from '../types';
import { analyzeCoinImage, generateNarrationAudio } from '../services/geminiService';

export const CoinAnalyzer: React.FC = () => {
  const [status, setStatus] = useState<AnalysisStatus>(AnalysisStatus.IDLE);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<CoinAnalysisResult | null>(null);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioRef = useRef<HTMLAudioElement>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Reset state
    setStatus(AnalysisStatus.ANALYZING);
    setResult(null);
    setAudioUrl(null);
    setErrorMsg(null);

    try {
      // Convert to Base64
      const reader = new FileReader();
      reader.onloadend = async () => {
        const base64String = (reader.result as string).split(',')[1];
        setImage(reader.result as string);

        try {
          // 1. Analyze Image
          const analysis = await analyzeCoinImage(base64String);
          setResult(analysis);
          setStatus(AnalysisStatus.GENERATING_AUDIO);

          // 2. Generate Audio
          const url = await generateNarrationAudio(analysis.narrationScript);
          setAudioUrl(url);
          setStatus(AnalysisStatus.COMPLETE);
        } catch (err: any) {
          console.error(err);
          setErrorMsg(err.message || "Analysis failed");
          setStatus(AnalysisStatus.ERROR);
        }
      };
      reader.readAsDataURL(file);
    } catch (e) {
      console.error(e);
      setStatus(AnalysisStatus.ERROR);
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  // Clean up Blob URL on unmount
  useEffect(() => {
    return () => {
      if (audioUrl) URL.revokeObjectURL(audioUrl);
    };
  }, [audioUrl]);

  return (
    <div className="max-w-3xl mx-auto w-full p-4 space-y-6">

      {/* Upload Section */}
      <div 
        className={`border-2 border-dashed rounded-2xl p-8 text-center transition-all duration-300 ${
          image ? 'border-amber-500/50 bg-slate-800/50' : 'border-slate-600 hover:border-amber-400 hover:bg-slate-800'
        }`}
      >
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          accept="image/*" 
          className="hidden" 
        />

        {!image ? (
          <div className="cursor-pointer" onClick={triggerUpload}>
            <div className="w-16 h-16 bg-amber-500/10 rounded-full flex items-center justify-center mx-auto mb-4 text-amber-500">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-8 h-8">
                <path strokeLinecap="round" strokeLinejoin="round" d="M6.827 6.175A2.31 2.31 0 015.186 7.23c-.38.054-.757.112-1.134.175C2.999 7.58 2.25 8.507 2.25 9.574V18a2.25 2.25 0 002.25 2.25h15A2.25 2.25 0 0021.75 18V9.574c0-1.067-.75-1.994-1.802-2.169a47.865 47.865 0 00-1.134-.175 2.31 2.31 0 01-1.64-1.055l-.822-1.316a2.192 2.192 0 00-1.736-1.039 48.774 48.774 0 00-5.232 0 2.192 2.192 0 00-1.736 1.039l-.821 1.316z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 12.75a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zM18.75 10.5h.008v.008h-.008V10.5z" />
              </svg>
            </div>
            <h3 className="text-xl font-semibold text-slate-200">Identify Coin</h3>
            <p className="text-slate-400 mt-2">Upload or snap a photo of a coin to reveal its rarity.</p>
          </div>
        ) : (
          <div className="relative group">
             <img src={image} alt="Uploaded coin" className="max-h-64 mx-auto rounded-lg shadow-2xl object-contain" />
             <button 
                onClick={triggerUpload}
                className="absolute bottom-4 right-1/2 translate-x-1/2 bg-slate-900/80 text-white px-4 py-2 rounded-full text-sm hover:bg-black backdrop-blur-sm transition-colors"
             >
                Retake Photo
             </button>
          </div>
        )}
      </div>

      {/* Loading States */}
      {status === AnalysisStatus.ANALYZING && (
        <div className="text-center py-12">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-4 border-amber-500 border-t-transparent mb-4"></div>
          <p className="text-amber-400 animate-pulse font-medium">Analyzing mint marks and errors...</p>
        </div>
      )}

      {status === AnalysisStatus.GENERATING_AUDIO && result && (
        <div className="text-center py-12">
          <div className="inline-block animate-bounce rounded-full h-12 w-12 bg-indigo-500/20 text-indigo-400 flex items-center justify-center mb-4 mx-auto">
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
             </svg>
          </div>
          <p className="text-indigo-400 animate-pulse font-medium">Generating expert narration...</p>
        </div>
      )}

      {status === AnalysisStatus.ERROR && (
        <div className="bg-red-900/30 border border-red-500/50 p-4 rounded-lg text-center text-red-200">
          <p>Error: {errorMsg}</p>
          <button onClick={() => setStatus(AnalysisStatus.IDLE)} className="mt-2 text-sm underline hover:text-white">Try Again</button>
        </div>
      )}

      {/* Results */}
      {(status === AnalysisStatus.COMPLETE || (result && status === AnalysisStatus.GENERATING_AUDIO)) && result && (
        <div className="animate-fade-in-up space-y-6">

          {/* Main Score Card */}
          <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-amber-500/10 rounded-full -mr-16 -mt-16 blur-3xl"></div>

            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div>
                <span className="inline-block px-3 py-1 bg-slate-700 rounded-full text-xs font-medium text-slate-300 mb-2 uppercase tracking-wider">
                  {result.year} {result.mintMark}
                </span>
                <h2 className="text-3xl font-bold text-white mb-1">{result.coinName}</h2>
                <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-bold border ${
                  result.rarityScore >= 8 ? 'bg-purple-900/30 border-purple-500 text-purple-300' :
                  result.rarityScore >= 5 ? 'bg-amber-900/30 border-amber-500 text-amber-300' :
                  'bg-slate-700 border-slate-600 text-slate-300'
                }`}>
                  {result.rarityLevel}
                </div>
              </div>

              <div className="flex items-center gap-4 bg-slate-900/50 p-4 rounded-xl border border-slate-700/50">
                <div className="text-center">
                  <p className="text-xs text-slate-400 uppercase tracking-wide mb-1">Score</p>
                  <div className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-br from-amber-300 to-amber-600">
                    {result.rarityScore}<span className="text-lg text-slate-500 font-normal">/10</span>
                  </div>
                </div>
                <div className="w-px h-12 bg-slate-700"></div>
                <div className="text-center min-w-[80px]">
                  <p className="text-xs text-slate-400 uppercase tracking-wide mb-1">Est. Value</p>
                  <p className="text-xl font-bold text-emerald-400">{result.estimatedValue}</p>
                </div>
              </div>
            </div>

            <div className="mt-6 pt-6 border-t border-slate-700">
              <h4 className="text-sm font-medium text-slate-400 mb-2 uppercase">Reasoning</h4>
              <p className="text-slate-300 leading-relaxed">{result.reasoning}</p>
            </div>
          </div>

          {/* Audio Player Card */}
          <div className="bg-indigo-900/20 border border-indigo-500/30 rounded-xl p-6 flex flex-col sm:flex-row items-center gap-6">
            <div className="bg-indigo-600 w-12 h-12 rounded-full flex items-center justify-center flex-shrink-0 shadow-lg shadow-indigo-500/20">
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6 text-white">
                <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
              </svg>
            </div>

            <div className="flex-1 text-center sm:text-left">
              <h3 className="text-lg font-bold text-white mb-1">DeepMind Expert Analysis</h3>
              <p className="text-sm text-indigo-200/70 mb-3">Listen to a detailed breakdown of your coin's features.</p>

              {audioUrl ? (
                <audio 
                  ref={audioRef}
                  controls 
                  src={audioUrl} 
                  className="w-full h-8 accent-indigo-500"
                />
              ) : (
                <div className="h-8 bg-indigo-500/10 rounded w-full animate-pulse"></div>
              )}
            </div>
          </div>

        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { AnalysisStatus, CoinAnalysisResult } from '../types';
import { analyzeCoinImage, generateNarrationAudio } from '../services/geminiService';

export const CoinAnalyzer: React.FC = () => {
