                  <div className="flex flex-row md:flex-col items-center md:items-end gap-4 md:gap-1 bg-slate-900/30 p-3 rounded-lg w-full md:w-auto justify-between md:justify-start">
                    <div className="text-center md:text-right">
                      <p className="text-[10px] text-slate-500 uppercase tracking-wide">Score</p>
                      <div className="text-xl font-black text-amber-400">
                        {coin.rarityScore}<span className="text-sm text-slate-600 font-normal">/10</span>
                      </div>
                    </div>
                    <div className="h-8 w-px bg-slate-700 md:hidden"></div>
                    <div className="text-center md:text-right">
                      <p className="text-[10px] text-slate-500 uppercase tracking-wide">Est. Value</p>
                      <p className="text-lg font-bold text-emerald-400">{coin.estimatedValue}</p>
                    </div>
                  </div>
                </div>

                <div className="mt-4 pt-4 border-t border-slate-700/50">
                  <p className="text-slate-300 text-sm leading-relaxed">{coin.reasoning}</p>
                </div>
              </div>
            ))}
          </div>

          {/* NEW: Bottom Action Buttons for easy resetting */}
          <div className="flex flex-col sm:flex-row justify-center gap-4 mt-8 pb-8">
            <button 
              onClick={triggerCamera}
              className="flex items-center justify-center gap-2 bg-amber-600 hover:bg-amber-500 text-white px-8 py-4 rounded-xl font-bold shadow-lg shadow-amber-900/20 transition-transform hover:scale-105"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M6.827 6.175A2.31 2.31 0 015.186 7.23c-.38.054-.757.112-1.134.175C2.999 7.58 2.25 8.507 2.25 9.574V18a2.25 2.25 0 002.25 2.25h15A2.25 2.25 0 0021.75 18V9.574c0-1.067-.75-1.994-1.802-2.169a47.865 47.865 0 00-1.134-.175 2.31 2.31 0 01-1.64-1.055l-.822-1.316a2.192 2.192 0 00-1.736-1.039 48.774 48.774 0 00-5.232 0 2.192 2.192 0 00-1.736 1.039l-.821 1.316z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M16.5 12.75a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zM18.75 10.5h.008v.008h-.008V10.5z" />
              </svg>
              Take New Photo
            </button>
            <button 
              onClick={triggerUpload}
              className="flex items-center justify-center gap-2 bg-slate-700 hover:bg-slate-600 text-slate-200 px-8 py-4 rounded-xl font-bold shadow-lg transition-colors hover:text-white"
            >
              <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5m-13.5-9L12 3m0 0l4.5 4.5M12 3v13.5" />
              </svg>
              Upload Different Image
            </button>
          </div>

        </div>
      )}
    </div>
  );
};
